package com.example.finance.data

import android.content.Context
import com.example.finance.auth.SupabaseAuthRepository
import com.example.finance.model.*
import com.example.finance.supabase.SupabaseConnection
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONArray
import org.json.JSONObject
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import java.util.UUID

/** Remote data facade. All financial records live in Supabase; no local database is used. */
class FinanceDao(context: Context) {
    private val auth = SupabaseAuthRepository(context.applicationContext)
    private val client = OkHttpClient()
    private val jsonType = "application/json; charset=utf-8".toMediaType()
    private val scope = CoroutineScope(Dispatchers.IO)
    private val date = SimpleDateFormat("yyyy-MM-dd", Locale.US)

    private val _accounts=MutableStateFlow<List<AccountEntity>>(emptyList()); private val _transactions=MutableStateFlow<List<TransactionEntity>>(emptyList()); private val _transfers=MutableStateFlow<List<TransferEntity>>(emptyList()); private val _budgets=MutableStateFlow<List<BudgetEntity>>(emptyList()); private val _debts=MutableStateFlow<List<DebtEntity>>(emptyList()); private val _debtPayments=MutableStateFlow<List<DebtPaymentEntity>>(emptyList()); private val _bills=MutableStateFlow<List<BillEntity>>(emptyList()); private val _goals=MutableStateFlow<List<SavingsGoalEntity>>(emptyList()); private val _assets=MutableStateFlow<List<AssetEntity>>(emptyList()); private val _members=MutableStateFlow<List<HouseholdMemberEntity>>(emptyList()); private val _expenses=MutableStateFlow<List<HouseholdExpenseEntity>>(emptyList()); private val _houseBudgets=MutableStateFlow<List<HouseholdBudgetEntity>>(emptyList()); private val _documents=MutableStateFlow<List<DocumentEntity>>(emptyList()); private val _notifications=MutableStateFlow<List<NotificationEntity>>(emptyList()); private val _audit=MutableStateFlow<List<AuditLogEntity>>(emptyList()); private val _user=MutableStateFlow<UserEntity?>(null)
    private val maps=mutableMapOf<String,MutableMap<Long,String>>()

    init { scope.launch { refreshAll() } }
    private fun map(table:String)=maps.getOrPut(table){mutableMapOf()}
    private fun localId(uuid:String):Long { val u=UUID.fromString(uuid); var x=u.mostSignificantBits xor u.leastSignificantBits; if(x==0L)x=1L; return x }
    private suspend fun token()=auth.accessToken()?.takeIf{it.isNotBlank()} ?: throw IllegalStateException("No active Supabase session")
    private fun req(path:String,t:String)=Request.Builder().url(SupabaseConnection.url.trimEnd('/')+"/rest/v1/"+path).header("apikey",SupabaseConnection.publishableKey).header("Authorization","Bearer $t").header("Accept","application/json")
    private fun call(r:Request):String { client.newCall(r).execute().use{res->val b=res.body?.string().orEmpty();if(!res.isSuccessful)throw IllegalStateException("Supabase HTTP ${res.code}: $b");return b} }
    private fun d(v:Long)=synchronized(date){date.format(Date(v))}; private fun p(v:String?)=synchronized(date){v?.let{date.parse(it)?.time}?:System.currentTimeMillis()}
    private suspend fun get(table:String,select:String="*"):JSONArray=withContext(Dispatchers.IO){JSONArray(call(req("$table?select=$select",token()).get().build()))}
    private suspend fun write(table:String,remote:String?,payload:JSONObject):String=withContext(Dispatchers.IO){val t=token();if(remote.isNullOrBlank()){val a=JSONArray(call(req(table,t).header("Prefer","return=representation").post(payload.toString().toRequestBody(jsonType)).build()));a.getJSONObject(0).getString("id")}else{call(req("$table?id=eq.$remote",t).header("Prefer","return=minimal").patch(payload.toString().toRequestBody(jsonType)).build());remote}}
    private suspend fun remove(table:String,remote:String){if(remote.isBlank())return;call(req("$table?id=eq.$remote",token()).delete().build())}

    suspend fun refreshAll(){runCatching{
        refreshAccounts();refreshTransactions();refreshTransfers();refreshBudgets();refreshDebts();refreshDebtPayments();refreshBills();refreshGoals();refreshAssets();refreshMembers();refreshExpenses();refreshHouseBudgets();refreshDocuments();refreshNotifications();refreshAudit();refreshUser()
    }}
    private suspend fun refreshAccounts(){val a=get("accounts");val out=mutableListOf<AccountEntity>();map("accounts").clear();for(i in 0 until a.length()){val r=a.getJSONObject(i);val id=r.getString("id");val l=localId(id);map("accounts")[l]=id;out+=AccountEntity(l,r.optString("name"),enum(r.optString("type"),AccountType.CASH),r.optString("currency_code","LYD"),r.optDouble("current_balance"),r.optDouble("opening_balance"),r.optString("last_four"),r.optString("institution_name"),!r.optBoolean("is_active",true),remoteId=id)};_accounts.value=out}
    private suspend fun refreshTransactions(){val a=get("transactions","*");val out=mutableListOf<TransactionEntity>();map("transactions").clear();for(i in 0 until a.length()){val r=a.getJSONObject(i);val id=r.getString("id");val l=localId(id);map("transactions")[l]=id;val aid=map("accounts").entries.firstOrNull{it.value==r.optString("account_id")}?.key?:0;out+=TransactionEntity(l,aid,enum(r.optString("type"),TransactionType.EXPENSE),r.optDouble("amount"),r.optString("currency_code","LYD"),r.optString("category_id","Uncategorized"),p(r.optString("transaction_date")),r.optString("description"),merchant=r.optString("reference"),status=enum(r.optString("status"),TransactionStatus.COMPLETED),remoteId=id)};_transactions.value=out.sortedByDescending{it.date}}
    private suspend fun refreshTransfers(){val a=get("transfers");val out=mutableListOf<TransferEntity>();map("transfers").clear();for(i in 0 until a.length()){val r=a.getJSONObject(i);val id=r.getString("id");val l=localId(id);map("transfers")[l]=id;out+=TransferEntity(l,map("accounts").entries.firstOrNull{it.value==r.optString("from_account_id")}?.key?:0,map("accounts").entries.firstOrNull{it.value==r.optString("to_account_id")}?.key?:0,r.optDouble("amount"),r.optDouble("fee"),r.optString("currency_code","LYD"),p(r.optString("transfer_date")),r.optString("description"),remoteId=id)};_transfers.value=out}
    private suspend fun refreshBudgets(){val a=get("budgets");val out=mutableListOf<BudgetEntity>();map("budgets").clear();for(i in 0 until a.length()){val r=a.getJSONObject(i);val id=r.getString("id");val l=localId(id);map("budgets")[l]=id;out+=BudgetEntity(l,r.optString("name"),r.optString("category_id","All categories"),enum(r.optString("period"),BudgetPeriod.MONTHLY),r.optDouble("amount"),r.optString("currency_code","LYD"),p(r.optString("start_date")),r.optString("end_date").takeIf{it.isNotBlank()}?.let(::p)?:p(r.optString("start_date")),id)};_budgets.value=out}
    private suspend fun refreshDebts(){val a=get("debts");val out=mutableListOf<DebtEntity>();map("debts").clear();for(i in 0 until a.length()){val r=a.getJSONObject(i);val id=r.getString("id");val l=localId(id);map("debts")[l]=id;val settled=r.optBoolean("is_settled");out+=DebtEntity(l,r.optString("person_name"),r.optString("person_name"),r.optDouble("principal_amount"),r.optDouble("remaining_amount"),0.0,p(r.optString("due_date")),0.0,r.optString("currency_code","LYD"),if(settled)DebtStatus.PAID else DebtStatus.ACTIVE,r.optString("notes"),r.optString("type","i_owe"),id)};_debts.value=out}
    private suspend fun refreshDebtPayments(){val a=get("debt_payments");val out=mutableListOf<DebtPaymentEntity>();map("debt_payments").clear();for(i in 0 until a.length()){val r=a.getJSONObject(i);val id=r.getString("id");val l=localId(id);map("debt_payments")[l]=id;out+=DebtPaymentEntity(l,map("debts").entries.firstOrNull{it.value==r.optString("debt_id")}?.key?:0,r.optDouble("amount"),p(r.optString("payment_date")),r.optString("notes"),r.optString("currency_code","LYD"),id)};_debtPayments.value=out}
    private suspend fun refreshBills(){val a=get("bills");val out=mutableListOf<BillEntity>();map("bills").clear();for(i in 0 until a.length()){val r=a.getJSONObject(i);val id=r.getString("id");val l=localId(id);map("bills")[l]=id;out+=BillEntity(l,r.optString("name"),"",r.optDouble("amount"),r.optString("currency_code","LYD"),p(r.optString("due_date")),r.optString("recurrence").isNotBlank(),30,r.optString("status")=="paid",3,id)};_bills.value=out}
    private suspend fun refreshGoals(){val a=get("savings_goals");val out=mutableListOf<SavingsGoalEntity>();map("savings_goals").clear();for(i in 0 until a.length()){val r=a.getJSONObject(i);val id=r.getString("id");val l=localId(id);map("savings_goals")[l]=id;out+=SavingsGoalEntity(l,r.optString("name"),r.optDouble("target_amount"),r.optDouble("current_amount"),r.optString("currency_code","LYD"),p(r.optString("target_date")),0.0,"#D6B56D",id)};_goals.value=out}
    private suspend fun refreshAssets(){val a=get("assets");val out=mutableListOf<AssetEntity>();map("assets").clear();for(i in 0 until a.length()){val r=a.getJSONObject(i);val id=r.getString("id");val l=localId(id);map("assets")[l]=id;out+=AssetEntity(l,r.optString("name"),enum(r.optString("asset_type"),AssetType.OTHER),r.optDouble("estimated_value"),r.optString("currency_code","LYD"),p(r.optString("acquired_date")),r.optString("notes"),id)};_assets.value=out}
    private suspend fun refreshMembers(){val a=get("household_members");val out=mutableListOf<HouseholdMemberEntity>();map("household_members").clear();for(i in 0 until a.length()){val r=a.getJSONObject(i);val id=r.getString("id");val l=localId(id);map("household_members")[l]=id;out+=HouseholdMemberEntity(l,r.optString("name"),r.optString("role","family"),monthlyContribution=r.optDouble("monthly_contribution"),isActive=r.optBoolean("is_active",true),remoteId=id)};_members.value=out}
    private suspend fun refreshExpenses(){val a=get("household_expenses");val out=mutableListOf<HouseholdExpenseEntity>();map("household_expenses").clear();for(i in 0 until a.length()){val r=a.getJSONObject(i);val id=r.getString("id");val l=localId(id);map("household_expenses")[l]=id;out+=HouseholdExpenseEntity(l,r.optString("description"),r.optDouble("amount"),map("household_members").entries.firstOrNull{it.value==r.optString("member_id")}?.key,r.optString("category","عام"),r.optString("currency_code","LYD"),p(r.optString("expense_date")),false,r.optBoolean("is_recurring"),r.optString("notes"),id)};_expenses.value=out}
    private suspend fun refreshHouseBudgets(){val a=get("household_budgets");val out=mutableListOf<HouseholdBudgetEntity>();map("household_budgets").clear();for(i in 0 until a.length()){val r=a.getJSONObject(i);val id=r.getString("id");val l=localId(id);map("household_budgets")[l]=id;out+=HouseholdBudgetEntity(l,r.optString("name"),r.optDouble("amount"),r.optString("currency_code","LYD"),r.optString("period","monthly"),p(r.optString("start_date")),r.optString("end_date").takeIf{it.isNotBlank()}?.let(::p),r.optBoolean("is_active",true),id)};_houseBudgets.value=out}
    private suspend fun refreshDocuments(){val a=get("documents");val out=mutableListOf<DocumentEntity>();map("documents").clear();for(i in 0 until a.length()){val r=a.getJSONObject(i);val id=r.getString("id");val l=localId(id);map("documents")[l]=id;out+=DocumentEntity(l,r.optString("file_name"),enum(r.optString("document_type"),DocumentType.OTHER),r.optString("storage_path"),remoteId=id)};_documents.value=out}
    private suspend fun refreshNotifications(){val a=get("notifications");val out=mutableListOf<NotificationEntity>();map("notifications").clear();for(i in 0 until a.length()){val r=a.getJSONObject(i);val id=r.getString("id");val l=localId(id);map("notifications")[l]=id;out+=NotificationEntity(l,r.optString("title"),r.optString("body"),enum(r.optString("type"),NotificationType.AI_INSIGHT),p(r.optString("created_at")),r.optBoolean("is_read"),id)};_notifications.value=out}
    private suspend fun refreshAudit(){val a=get("audit_logs");val out=mutableListOf<AuditLogEntity>();map("audit_logs").clear();for(i in 0 until a.length()){val r=a.getJSONObject(i);val id=r.getString("id");val l=localId(id);map("audit_logs")[l]=id;out+=AuditLogEntity(l,r.optString("action"),r.optString("entity_type"),r.optString("metadata"),timestamp=p(r.optString("created_at")),remoteId=id)};_audit.value=out}
    private suspend fun refreshUser(){val uid=auth.currentUserId().getOrNull()?:return;val a=get("profiles","*");val r=(0 until a.length()).map{a.getJSONObject(it)}.firstOrNull{it.optString("id")==uid}?:return;_user.value=UserEntity(localId(uid),r.optString("full_name"),"",currencyPreference=r.optString("currency_code","LYD"),languagePreference=if(r.optString("locale").startsWith("en"))AppLanguage.EN else AppLanguage.AR,remoteId=uid)}

    fun getAllAccounts():Flow<List<AccountEntity>> =_accounts; fun getArchivedAccounts():Flow<List<AccountEntity>> =_accounts.let{MutableStateFlow(it.value.filter(AccountEntity::isArchived))}; suspend fun getAccountById(id:Long)=_accounts.value.firstOrNull{it.id==id}
    suspend fun insertAccount(x:AccountEntity):Long{val r=write("accounts",x.remoteId.takeIf{it.isNotBlank()},JSONObject().put("name",x.name).put("type",x.type.name.lowercase()).put("currency_code",x.currency).put("opening_balance",x.openingBalance).put("current_balance",x.balance).put("institution_name",x.institution).put("last_four",x.accountNumberSafe).put("is_active",!x.isArchived).put("user_id",auth.currentUserId().getOrThrow()));refreshAccounts();return localId(r)}
    suspend fun updateAccount(x:AccountEntity){write("accounts",map("accounts")[x.id],JSONObject().put("name",x.name).put("current_balance",x.balance).put("is_active",!x.isArchived).put("institution_name",x.institution).put("last_four",x.accountNumberSafe));refreshAccounts()}
    suspend fun updateAccountBalance(id:Long,b:Double){val r=map("accounts")[id]?:return;write("accounts",r,JSONObject().put("current_balance",b));refreshAccounts()}; suspend fun setAccountArchived(id:Long,v:Boolean){updateAccount(_accounts.value.first{it.id==id}.copy(isArchived=v))}; suspend fun deleteAccount(x:AccountEntity){remove("accounts",map("accounts")[x.id].orEmpty());refreshAccounts()}
    fun getAllTransactions():Flow<List<TransactionEntity>> =_transactions; suspend fun getAllTransactionsSnapshot()=_transactions.value; fun getTransactionsByAccount(id:Long):Flow<List<TransactionEntity>> =MutableStateFlow(_transactions.value.filter{it.accountId==id})
    suspend fun insertTransaction(x:TransactionEntity):Long{val ar=map("accounts")[x.accountId]?:throw IllegalStateException("Account not found");val r=write("transactions",null,JSONObject().put("user_id",auth.currentUserId().getOrThrow()).put("account_id",ar).put("type",x.type.name.lowercase()).put("status",x.status.name.lowercase()).put("amount",x.amount).put("currency_code",x.currency).put("description",x.description).put("transaction_date",d(x.date)).put("reference",x.merchant));refreshTransactions();return localId(r)}
    suspend fun updateTransaction(x:TransactionEntity){write("transactions",map("transactions")[x.id],JSONObject().put("status",x.status.name.lowercase()).put("amount",x.amount).put("description",x.description).put("transaction_date",d(x.date)).put("reference",x.merchant));refreshTransactions()}; suspend fun deleteTransaction(x:TransactionEntity){remove("transactions",map("transactions")[x.id].orEmpty());refreshTransactions()}
    fun getAllTransfers():Flow<List<TransferEntity>> =_transfers; suspend fun insertTransfer(x:TransferEntity):Long{val r=write("transfers",null,JSONObject().put("user_id",auth.currentUserId().getOrThrow()).put("from_account_id",map("accounts")[x.fromAccountId]).put("to_account_id",map("accounts")[x.toAccountId]).put("amount",x.amount).put("fee",x.fee).put("currency_code",x.currency).put("description",x.description).put("transfer_date",d(x.date)).put("status","completed"));refreshTransfers();return localId(r)}
    fun getAllBudgets():Flow<List<BudgetEntity>> =_budgets; suspend fun insertBudget(x:BudgetEntity)=localWrite("budgets",x,JSONObject().put("name",x.name).put("amount",x.limitAmount).put("currency_code",x.currency).put("period",x.period.name.lowercase()).put("start_date",d(x.startDate)).put("end_date",d(x.endDate)).put("user_id",auth.currentUserId().getOrThrow())){refreshBudgets()}; suspend fun updateBudget(x:BudgetEntity)=remoteUpdate("budgets",x.remoteId,JSONObject().put("name",x.name).put("amount",x.limitAmount).put("currency_code",x.currency).put("period",x.period.name.lowercase()).put("start_date",d(x.startDate)).put("end_date",d(x.endDate))){refreshBudgets()}; suspend fun deleteBudget(x:BudgetEntity){remove("budgets",x.remoteId);refreshBudgets()}
    fun getAllDebts():Flow<List<DebtEntity>> =_debts; suspend fun getDebtById(id:Long)=_debts.value.firstOrNull{it.id==id}; suspend fun insertDebt(x:DebtEntity)=localWrite("debts",x,JSONObject().put("user_id",auth.currentUserId().getOrThrow()).put("person_name",x.name).put("type",x.direction).put("principal_amount",x.principal).put("remaining_amount",x.remaining).put("currency_code",x.currency).put("due_date",d(x.dueDate)).put("notes",x.notes).put("is_settled",x.status==DebtStatus.PAID)){refreshDebts()}; suspend fun updateDebt(x:DebtEntity)=remoteUpdate("debts",x.remoteId,JSONObject().put("person_name",x.name).put("type",x.direction).put("principal_amount",x.principal).put("remaining_amount",x.remaining).put("currency_code",x.currency).put("due_date",d(x.dueDate)).put("notes",x.notes).put("is_settled",x.status==DebtStatus.PAID)){refreshDebts()}; suspend fun deleteDebt(x:DebtEntity){remove("debts",x.remoteId);refreshDebts()}
    suspend fun insertDebtPayment(x:DebtPaymentEntity)=localWrite("debt_payments",x,JSONObject().put("user_id",auth.currentUserId().getOrThrow()).put("debt_id",map("debts")[x.debtId]).put("amount",x.amount).put("currency_code",x.currency).put("payment_date",d(x.date)).put("notes",x.notes)){refreshDebtPayments()}; fun getDebtPayments(id:Long):Flow<List<DebtPaymentEntity>> =MutableStateFlow(_debtPayments.value.filter{it.debtId==id})
    fun getAllBills():Flow<List<BillEntity>> =_bills; suspend fun getBillById(id:Long)=_bills.value.firstOrNull{it.id==id}; suspend fun insertBill(x:BillEntity)=localWrite("bills",x,JSONObject().put("user_id",auth.currentUserId().getOrThrow()).put("name",x.name).put("amount",x.amount).put("currency_code",x.currency).put("due_date",d(x.dueDate)).put("status",if(x.isPaid)"paid" else "upcoming").put("recurrence",if(x.isRecurring)x.recurrenceIntervalDays.toString() else "")){refreshBills()}; suspend fun updateBill(x:BillEntity)=remoteUpdate("bills",x.remoteId,JSONObject().put("name",x.name).put("amount",x.amount).put("currency_code",x.currency).put("due_date",d(x.dueDate)).put("status",if(x.isPaid)"paid" else "upcoming")){refreshBills()}; suspend fun deleteBill(x:BillEntity){remove("bills",x.remoteId);refreshBills()}
    fun getAllSavingsGoals():Flow<List<SavingsGoalEntity>> =_goals; suspend fun getSavingsGoalById(id:Long)=_goals.value.firstOrNull{it.id==id}; suspend fun insertSavingsGoal(x:SavingsGoalEntity)=localWrite("savings_goals",x,JSONObject().put("user_id",auth.currentUserId().getOrThrow()).put("name",x.name).put("target_amount",x.targetAmount).put("current_amount",x.currentAmount).put("currency_code",x.currency).put("target_date",d(x.deadline)).put("is_completed",x.currentAmount>=x.targetAmount)){refreshGoals()}; suspend fun updateSavingsGoal(x:SavingsGoalEntity)=remoteUpdate("savings_goals",x.remoteId,JSONObject().put("name",x.name).put("target_amount",x.targetAmount).put("current_amount",x.currentAmount).put("currency_code",x.currency).put("target_date",d(x.deadline)).put("is_completed",x.currentAmount>=x.targetAmount)){refreshGoals()}; suspend fun deleteSavingsGoal(x:SavingsGoalEntity){remove("savings_goals",x.remoteId);refreshGoals()}
    fun getAllAssets():Flow<List<AssetEntity>> =_assets; suspend fun insertAsset(x:AssetEntity)=localWrite("assets",x,JSONObject().put("user_id",auth.currentUserId().getOrThrow()).put("name",x.name).put("asset_type",x.type.name.lowercase()).put("estimated_value",x.value).put("currency_code",x.currency).put("acquired_date",d(x.purchaseDate)).put("notes",x.notes)){refreshAssets()}; suspend fun updateAsset(x:AssetEntity)=remoteUpdate("assets",x.remoteId,JSONObject().put("name",x.name).put("asset_type",x.type.name.lowercase()).put("estimated_value",x.value).put("currency_code",x.currency).put("acquired_date",d(x.purchaseDate)).put("notes",x.notes)){refreshAssets()}; suspend fun deleteAsset(x:AssetEntity){remove("assets",x.remoteId);refreshAssets()}
    fun getAllHouseholdMembers():Flow<List<HouseholdMemberEntity>> =_members; suspend fun getAllHouseholdMembersSnapshot()=_members.value; suspend fun getHouseholdMemberById(id:Long)=_members.value.firstOrNull{it.id==id}; suspend fun getHouseholdMemberByRemoteId(id:String)=_members.value.firstOrNull{it.remoteId==id}; suspend fun insertHouseholdMember(x:HouseholdMemberEntity)=localWrite("household_members",x,JSONObject().put("user_id",auth.currentUserId().getOrThrow()).put("name",x.name).put("role",x.role).put("monthly_contribution",x.monthlyContribution).put("is_active",x.isActive)){refreshMembers()}; suspend fun updateHouseholdMember(x:HouseholdMemberEntity)=remoteUpdate("household_members",x.remoteId,JSONObject().put("name",x.name).put("role",x.role).put("monthly_contribution",x.monthlyContribution).put("is_active",x.isActive)){refreshMembers()}; suspend fun deleteHouseholdMember(x:HouseholdMemberEntity){remove("household_members",x.remoteId);refreshMembers()}; suspend fun setHouseholdMemberRemoteId(id:Long,remoteId:String){}
    fun getAllHouseholdExpenses():Flow<List<HouseholdExpenseEntity>> =_expenses; suspend fun getAllHouseholdExpensesSnapshot()=_expenses.value; suspend fun getHouseholdExpenseByRemoteId(id:String)=_expenses.value.firstOrNull{it.remoteId==id}; suspend fun insertHouseholdExpense(x:HouseholdExpenseEntity)=localWrite("household_expenses",x,JSONObject().put("user_id",auth.currentUserId().getOrThrow()).put("member_id",x.payerMemberId?.let{map("household_members")[it]}?:JSONObject.NULL).put("category",x.category).put("description",x.title).put("amount",x.amount).put("currency_code",x.currency).put("expense_date",d(x.date)).put("is_recurring",x.isRecurring).put("notes",x.notes)){refreshExpenses()}; suspend fun updateHouseholdExpense(x:HouseholdExpenseEntity)=remoteUpdate("household_expenses",x.remoteId,JSONObject().put("member_id",x.payerMemberId?.let{map("household_members")[it]}?:JSONObject.NULL).put("category",x.category).put("description",x.title).put("amount",x.amount).put("currency_code",x.currency).put("expense_date",d(x.date)).put("is_recurring",x.isRecurring).put("notes",x.notes)){refreshExpenses()}; suspend fun deleteHouseholdExpense(x:HouseholdExpenseEntity){remove("household_expenses",x.remoteId);refreshExpenses()}; suspend fun setHouseholdExpenseRemoteId(id:Long,remoteId:String){}
    suspend fun clearHouseholdPayer(id:Long){_expenses.value.filter{it.payerMemberId==id}.forEach{updateHouseholdExpense(it.copy(payerMemberId=null))}}
    fun getAllHouseholdBudgets():Flow<List<HouseholdBudgetEntity>> =_houseBudgets; suspend fun getAllHouseholdBudgetsSnapshot()=_houseBudgets.value; suspend fun getHouseholdBudgetByRemoteId(id:String)=_houseBudgets.value.firstOrNull{it.remoteId==id}; suspend fun insertHouseholdBudget(x:HouseholdBudgetEntity)=localWrite("household_budgets",x,JSONObject().put("user_id",auth.currentUserId().getOrThrow()).put("name",x.name).put("amount",x.amount).put("currency_code",x.currencyCode).put("period",x.period).put("start_date",d(x.startDate)).put("end_date",x.endDate?.let(::d)?:JSONObject.NULL).put("is_active",x.isActive)){refreshHouseBudgets()}; suspend fun updateHouseholdBudget(x:HouseholdBudgetEntity)=remoteUpdate("household_budgets",x.remoteId,JSONObject().put("name",x.name).put("amount",x.amount).put("currency_code",x.currencyCode).put("period",x.period).put("start_date",d(x.startDate)).put("end_date",x.endDate?.let(::d)?:JSONObject.NULL).put("is_active",x.isActive)){refreshHouseBudgets()}; suspend fun deleteHouseholdBudget(x:HouseholdBudgetEntity){remove("household_budgets",x.remoteId);refreshHouseBudgets()}; suspend fun setHouseholdBudgetRemoteId(id:Long,remoteId:String){}
