    private suspend fun localWrite(table:String,x:Any,payload:JSONObject,after:suspend()->Unit):Long{val id=write(table,null,payload);after();return localId(id)}; private suspend fun remoteUpdate(table:String,id:String?,payload:JSONObject,after:suspend()->Unit){if(!id.isNullOrBlank())write(table,id,payload);after()}
    private inline fun <reified T:Enum<T>> enum(v:String,default:T):T=runCatching{enumValues<T>().first{it.name.equals(v.replace('-','_'),true)}}.getOrDefault(default)
